// 1. 密封接口配合 Record
public sealed interface Shape
    permits Circle, Rectangle, Triangle {
}

public record Circle(double radius) implements Shape {}
public record Rectangle(double width, double height) implements Shape {}
public final class Triangle implements Shape {
    private final double a, b, c;
    public Triangle(double a, double b, double c) {
        this.a = a; this.b = b; this.c = c;
    }
}

// 2. 密封类
public abstract sealed class PaymentMethod
    permits CreditCard, BankTransfer, Cash {
}
public final class CreditCard extends PaymentMethod {
    private final String cardNumber;
    public CreditCard(String cardNumber) { this.cardNumber = cardNumber; }
}
public non-sealed class BankTransfer extends PaymentMethod {
    // non-sealed: 允许任意继承
    private final String bankAccount;
    public BankTransfer(String bankAccount) { this.bankAccount = bankAccount; }
}
public record Cash() extends PaymentMethod {}

// 3. 配合 switch 模式匹配（Java 21）
String describe(Shape shape) {
    return switch (shape) {
        case Circle c    -> "圆，半径=" + c.radius();
        case Rectangle r -> "矩形，宽=" + r.width() + " 高=" + r.height();
        case Triangle t  -> "三角形";
        // 不需要 default，编译器确认穷举
    };
}
